def is_wait(text):
    return bool(re.match(r'^(?:i )?wait\b',text.strip(),re.I))


def wait_limit(state,text):
    seconds=duration_seconds(text)
    if seconds is not None:return min(seconds,2592000)
    m=re.search(r'until (dawn|morning|dark|dusk|noon|midnight)\b',text,re.I)
    if m:
        dest={'dawn':6,'morning':8,'dark':20,'dusk':18,'noon':12,'midnight':0}[m[1].lower()]*3600
        return (dest-state.world_seconds%DAY)%DAY or DAY
    return 3600 if re.search(r'\buntil\b',text,re.I) else 600


